197	#[inline]
198	fn parse_fragment(p: &mut GraphqlParser) -> ParsedSyntax {
199	    if !is_at_fragment(p) {
200	        return Absent;
201	    }
202	    let m = p.start();
203	    p.bump(DOT3);
204	    if is_at_name(p) {
205	        // name is checked for in `is_at_name`
206	        parse_name(p).ok();
207	        DirectiveList.parse_list(p);
208	        Present(m.complete(p, GRAPHQL_FRAGMENT_SPREAD))
209	    } else {
210	        if is_at_type_condition(p) {
211	            parse_type_condition(p);
212	        }
213	        DirectiveList.parse_list(p);
214	        parse_selection_set(p).ok();
215	        Present(m.complete(p, GRAPHQL_INLINE_FRAGMENT))
216	    }
217	}
