103	pub(crate) fn parse_value(p: &mut GraphqlParser) -> ParsedSyntax {
104	    if is_at_variable(p) {
105	        parse_variable(p)
106	    } else if is_at_int(p) {
107	        parse_int(p)
108	    } else if is_at_float(p) {
109	        parse_float(p)
110	    } else if is_at_string(p) {
111	        parse_string(p)
112	    } else if is_at_boolean(p) {
113	        parse_boolean(p)
114	    } else if is_at_null(p) {
115	        parse_null(p)
116	    } else if is_at_enum(p) {
117	        parse_enum(p)
118	    } else if is_at_list(p) {
119	        parse_list(p)
120	    } else if is_at_object(p) {
121	        parse_object(p)
122	    } else {
123	        return Absent;
124	    }
125	}
